// =====================================================
// Crawl website → clean text + emails + evidence URLs
// Mode: Run Once for Each Item
// v2: strips repeated navigation, skips listing/news pages,
//     keeps only company + freemail addresses
// =====================================================
const lead = $json;
const out = { ...lead, crawl_ok: false, crawl_error: "", site_text: "", emails_found: "", evidence_urls: "" };

if (!lead.website) { out.crawl_error = "no website"; return { json: out }; }

const helpers = this.helpers;
if (!helpers || !helpers.httpRequest) throw new Error("this.helpers.httpRequest not available in this n8n version");

const UA = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124 Safari/537.36";
const origin = lead.website.replace(/\/+$/, "");
const baseDomain = (lead.domain || "").toLowerCase();
const brand = baseDomain.split(".").slice(-2, -1)[0] || baseDomain;   // "strategis" from strategis.de

// ---------- helpers ----------
const fetchHtml = async (url) => {
  try {
    const body = await helpers.httpRequest({
      method: "GET", url,
      headers: { "User-Agent": UA, "Accept-Language": "de-DE,de;q=0.9" },
      timeout: 8000, json: false, skipSslCertificateValidation: true,
    });
    return typeof body === "string" ? body : (body ? String(body) : "");
  } catch (e) { return ""; }
};

const decode = (s) => s
  .replace(/&nbsp;/g, " ").replace(/&amp;/g, "&").replace(/&quot;/g, '"').replace(/&#39;|&apos;/g, "'")
  .replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&shy;/g, "").replace(/&times;/g, "")
  .replace(/&auml;/g, "ä").replace(/&ouml;/g, "ö").replace(/&uuml;/g, "ü")
  .replace(/&Auml;/g, "Ä").replace(/&Ouml;/g, "Ö").replace(/&Uuml;/g, "Ü").replace(/&szlig;/g, "ß")
  .replace(/&sect;/g, "§").replace(/&ndash;|&mdash;/g, "–")
  .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(parseInt(n, 10)));

const htmlToText = (html) => decode(
  html
    .replace(/<script[\s\S]*?<\/script>/gi, " ")
    .replace(/<style[\s\S]*?<\/style>/gi, " ")
    .replace(/<noscript[\s\S]*?<\/noscript>/gi, " ")
    .replace(/<svg[\s\S]*?<\/svg>/gi, " ")
    .replace(/<nav[\s\S]*?<\/nav>/gi, " ")        // drop navigation menus
    .replace(/<form[\s\S]*?<\/form>/gi, " ")      // drop search/contact forms
    .replace(/<(br|\/p|\/div|\/li|\/h\d|\/tr|\/section)[^>]*>/gi, "\n")
    .replace(/<[^>]+>/g, " ")
).replace(/[ \t]+/g, " ").replace(/\n\s*\n+/g, "\n").trim();

const hostOf = (u) => { const m = u.match(/^https?:\/\/([^\/?#:]+)/i); return m ? m[1].toLowerCase().replace(/^www\./, "") : ""; };
const pathOf = (u) => { const m = u.match(/^https?:\/\/[^\/?#]+(\/[^?#]*)?/i); return (m && m[1]) ? m[1].toLowerCase() : "/"; };

const resolve = (href) => {
  if (/^(mailto:|tel:|javascript:|#)/i.test(href)) return null;
  if (/\.(pdf|jpe?g|png|gif|zip|docx?|xlsx?)(\?|$)/i.test(href)) return null;
  if (/^https?:\/\//i.test(href)) return href;
  if (href.startsWith("//")) return "https:" + href;
  if (href.startsWith("/")) return origin + href;
  return origin + "/" + href.replace(/^\.\//, "");
};

// Pages we never want: listings, news, jobs, legal boilerplate
const EXCLUDE = /\/(immobilien|immobilienangebote|angebote|mietangebote|kaufangebote|wohnungssuche|wohnung-mieten|wohnung-kaufen|expose|objekte?|neuigkeiten|news|blog|presse|karriere|jobs|datenschutz|agb|cookie|login|ratgeber|referenzen|downloads|mediathek)(\/|$)/i;

// ---------- 1. homepage ----------
let homeUrl = lead.website;
let homeHtml = await fetchHtml(homeUrl);
if (!homeHtml) {
  homeUrl = homeUrl.startsWith("https://") ? homeUrl.replace("https://", "http://") : homeUrl.replace("http://", "https://");
  homeHtml = await fetchHtml(homeUrl);
}
if (!homeHtml) { out.crawl_error = "website not reachable"; return { json: out }; }

// ---------- 2. find relevant subpages ----------
// [category, URL-path regex, anchor-text regex, max pages]
const CATS = [
  ["impressum", /impressum|imprint/i,                                                        /impressum|imprint/i, 1],
  ["services",  /leistung|service|verwaltung|weg|sondereigentum/i,                           /leistung|verwaltung|service/i, 2],
  ["about",     /\/(ueber-uns|uber-uns|über-uns|about(-us)?|unternehmen|wir-ueber-uns|philosophie)(\/|$)/i, /^(über uns|ueber uns|unternehmen|about( us)?|wir über uns)$/i, 1],
  ["team",      /team|ansprechpartner|geschaeftsfuehrung|geschäftsführung/i,                 /team|ansprechpartner|geschäftsführung/i, 1],
  ["partner",   /partner|kooperation/i,                                                       /partner/i, 1],
];

const links = [];
const re = /<a\s[^>]*href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi;
let m;
while ((m = re.exec(homeHtml)) !== null) {
  const abs = resolve(m[1].trim());
  if (!abs) continue;
  if (baseDomain && !hostOf(abs).endsWith(baseDomain)) continue;   // same site only
  const url = abs.split("#")[0];
  if (EXCLUDE.test(pathOf(url))) continue;                          // skip listings/news/jobs
  links.push({ url, path: pathOf(url), text: htmlToText(m[2]).toLowerCase().trim() });
}

const picked = [];
const norm = (u) => u.replace(/^https?:\/\/(www\.)?/i, "").replace(/\/+$/, "").toLowerCase();
const used = new Set([norm(homeUrl)]);
for (const [cat, urlRx, textRx, max] of CATS) {
  let count = 0;
  for (const l of links) {
    if (count >= max) break;
    const key = norm(l.url);
    if (used.has(key)) continue;
    if (urlRx.test(l.path) || textRx.test(l.text)) {
      picked.push({ cat, url: l.url });
      used.add(key);
      count++;
    }
  }
}
const subpages = picked.slice(0, 5);

// ---------- 3. fetch subpages ----------
const started = Date.now();
const pages = [{ cat: "homepage", url: homeUrl, html: homeHtml }];
for (const p of subpages) {
  if (Date.now() - started > 25000) break;   // slow site → stop, use what we have
  const html = await fetchHtml(p.url);
  if (html) pages.push({ ...p, html });
}

// ---------- 4. emails: company domain + freemail only ----------
const FREEMAIL = /@(gmail\.com|googlemail\.com|web\.de|gmx\.(de|net)|t-online\.de|outlook\.(de|com)|hotmail\.(de|com)|yahoo\.(de|com)|freenet\.de|arcor\.de|posteo\.de)$/;
const allHtml = pages.map(p => p.html).join(" ").replace(/&#64;|\[at\]|\(at\)/gi, "@");
const emails = [...new Set((allHtml.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi) || [])
  .map(e => e.toLowerCase())
  .filter(e => !/\.(png|jpe?g|gif|webp|svg)$/.test(e))
  .filter(e => e.split("@")[1].includes(brand) || FREEMAIL.test(e)))].slice(0, 10);

// ---------- 5. text: remove lines already seen on the homepage (repeated menus/footers) ----------
const LIMITS = { homepage: 4000, impressum: 3000, services: 3500, about: 3000, team: 3000, partner: 2000 };
const seenLines = new Set();
let siteText = "";
for (const p of pages) {
  const lines = htmlToText(p.html).split("\n").map(s => s.trim()).filter(Boolean);
  const fresh = lines.filter(line => {
    if (seenLines.has(line)) return false;     // already shown on an earlier page
    seenLines.add(line);
    return true;
  });
  const t = fresh.join("\n").slice(0, LIMITS[p.cat] || 2500);
  siteText += `\n\n=== PAGE: ${p.cat.toUpperCase()} (${p.url}) ===\n${t}`;
}

out.crawl_ok = true;
out.site_text = siteText.slice(0, 18000);
out.emails_found = emails.join(", ");
out.evidence_urls = pages.map(p => p.url).join(" | ");
return { json: out };

// Segment each lead before spending LLM calls on it
const core = ["Hausverwaltungsunternehmen", "Immobilienverwaltungsservice"];
const broker = ["Immobilienagentur", "Immobilienmakler", "Immobilienvermittlung", "Immobilienberater", "Wohnungsvermietungsagentur"];
const housing = ["Wohnungsbaugenossenschaft", "Wohnungsbaugesellschaft", "Sozialwohnungsbaugesellschaft", "Wohnungsbau", "Wohnungsbauunternehmen", "Wohnanlage/Wohnsiedlung"];
const nameRescue = /(verwaltung|immobil|wohn|hausverw|property|grundbesitz|management)/i;

return $input.all().map(({ json: r }) => {
  const cats = (r.all_categories || "").split(",").map(s => s.trim());
  const g = r.google_category || "";
  let segment;

  if (!(r.city || "").toLowerCase().includes("berlin")) segment = "outside_berlin";
  else if (core.includes(g) || cats.some(c => core.includes(c))) segment = "core";
  else if (housing.includes(g) || /genossenschaft|wohnungsbau/i.test(r.company_name)) segment = "housing_company";
  else if (broker.includes(g)) segment = "broker_category";
  else if (nameRescue.test(r.company_name)) segment = "check";   // odd category, but the name looks relevant
  else segment = "irrelevant";

  return { json: { ...r, segment, enrich: ["core", "broker_category", "check"].includes(segment) } };
});

// =====================================================
// Parse Claude JSON → guardrails → score → red flags → sheet row
// Mode: Run Once for Each Item
// =====================================================
const lead = $('Crawl website').item.json;
const raw = $json.text ?? $json.response?.generations?.[0]?.[0]?.text ?? "";
const now = new Date().toISOString();

// ---------- 1. parse JSON safely ----------
let k = null, parseError = "";
try {
  const cleaned = String(raw).replace(/```json|```/gi, "").trim();
  k = JSON.parse(cleaned.slice(cleaned.indexOf("{"), cleaned.lastIndexOf("}") + 1));
} catch (e) {
  parseError = String(e.message || e);
}

if (!k) {
  return { json: {
    place_id: lead.place_id, status: "enrich_failed",
    needs_review: "yes – LLM output not parseable: " + parseError.slice(0, 80),
    evidence_urls: lead.evidence_urls || "", enriched_at: now,
  }};
}

// ---------- 2. guardrails (code double-checks the LLM) ----------
const text = lead.site_text || "";
const guardNotes = [];

if (/(betriebskosten|nebenkosten|heizkosten|hausgeld)[-\s]?abrechnung|jahresabrechnung/i.test(text) && !k.does_billing) {
  k.does_billing = true; guardNotes.push("billing set by keyword");
}

// WEG evidence in the text (services or staff roles) overrides a missed classification.
// Case-sensitive "WEG" so the German word "weg" (= away) does not match.
const wegEvidence = /\bWEG[- ]?(Verwalt|Buchhalt)|Wohnungseigentumsverwalt|Wohnungseigentümergemeinschaft/.test(text);
if (wegEvidence && !k.manages_weg && ["broker", "mixed", "property_management"].includes(k.core_business)) {
  k.manages_weg = true;
  guardNotes.push("WEG set by keyword");
  if (k.core_business === "broker") {
    k.core_business = "mixed";
    guardNotes.push("broker → mixed (has WEG team)");
  }
}

if (k.manages_weg) {
  if (!k.manages_whole_buildings) guardNotes.push("whole_buildings implied by WEG");
  k.manages_whole_buildings = true;
  k.does_billing = true;          // WEG managers must produce annual statements by law
  k.sev_only = false;
}
if (k.sev_only) k.manages_whole_buildings = false;
if (!k.units_number) k.units_stated = k.units_stated && /verwalt|betreu|einheiten/i.test(k.units_stated) ? k.units_stated : null;



// ---------- 3. size category (stated numbers first, Google reviews as weak proxy) ----------
const units = Number(k.units_number) || 0;
const emp = Number(k.employees) || 0;
const reviews = Number(lead.google_reviews) || 0;
let size, sizePts;
if (units >= 1000 || emp >= 20)      { size = "Large";  sizePts = 10; }
else if (units >= 200 || emp >= 6)   { size = "Medium"; sizePts = 10; }
else if (units > 0 || emp > 0)       { size = "Small";  sizePts = 5; }
else if (reviews >= 150)             { size = "Medium (proxy: Google reviews)"; sizePts = 7; }
else if (reviews >= 30)              { size = "Small (proxy: Google reviews)";  sizePts = 5; }
else                                 { size = "Unknown"; sizePts = 3; }

// ---------- 4. existing Heidi customers (from heidi-systems.de logo list) ----------
const EXISTING = /\b(vitec|dumax|harte hausverwaltung|raumgold|schleicher immobilien|niesen immobilien|neckar immobilienverwaltung|pro gera|werne immobilien)\b/i;
const nameBlob = `${lead.company_name} ${k.legal_name || ""} ${lead.domain || ""}`;
const existing = EXISTING.test(nameBlob);

// ---------- 5. scoring (weights = KPI_Definitions tab) ----------
const pts = {
  core:    ({ property_management: 15, mixed: 8 })[k.core_business] || 0,
  weg:     k.manages_weg ? 15 : 0,
  whole:   k.manages_whole_buildings ? 10 : 0,
  billing: k.does_billing ? 10 : 0,
  focus:   ({ residential: 10, mixed: 5, unknown: 3 })[k.property_focus] || 0,
  size:    sizePts,
  digital: ({ high: 10, medium: 6, basic: 2 })[k.digital_level] || 0,
  vdiv:    ["VDIV", "both"].includes(k.association) ? 10 : 0,
  energy:  k.energy_signal ? 5 : 0,
  growth:  k.growth_signal ? 5 : 0,
};
const score = Object.values(pts).reduce((a, b) => a + b, 0);
const breakdown = Object.entries(pts).map(([kk, v]) => `${kk} ${v}`).join(" · ");

// ---------- 6. red flags (override the score) ----------
const flags = [];
if (existing)                              flags.push("Existing Heidi customer");
if (k.own_metering)                        flags.push("Competitor – own metering");
if (k.core_business === "broker")          flags.push("Pure broker");
if (k.core_business === "owner_landlord")  flags.push("Owner/landlord – separate pitch");
if (["developer", "other"].includes(k.core_business)) flags.push("Not a property manager");
if (k.property_focus === "commercial")     flags.push("Commercial only");
if (k.sev_only)                            flags.push("SEV only – no building-level decision");
if (k.berlin_presence === "none")          flags.push("No Berlin presence");

let priority;
if (existing)                                     priority = "Existing customer";
else if (k.core_business === "owner_landlord")    priority = "Strategic – separate pitch";
else if (flags.length)                            priority = "Not a target";
else if (score >= 75)                             priority = "A";   // thresholds = KPI_Definitions B4:B5
else if (score >= 55)                             priority = "B";
else                                              priority = "C";

// ---------- 7. review flags ----------
const review = [];
if (k.conflicts) review.push("conflict: " + k.conflicts);
if (k.data_confidence === "low") review.push("low data confidence");
if (units > 50000 || emp > 5000) review.push("implausible number");
if (lead.generic_name === "yes") review.push("generic Google name – check legal_name");

// ---------- 8. contacts from the website ----------
const allEmails = (lead.emails_found || "").split(",").map(s => s.trim()).filter(Boolean);
const personal = (k.personal_emails || []).filter(e => allEmails.includes(e.toLowerCase()));
const general = allEmails.find(e => /^(info|kontakt|office|post|mail|hallo|hello|service|verwaltung)@/.test(e)) || allEmails.find(e => !personal.includes(e)) || "";

const yn = (b) => (b ? "yes" : "no");
const reasonPrefix = k.consolidator ? "[Consolidator – strategic account] " : "";

// ---------- 9. output = exact sheet column names ----------
return { json: {
  place_id: lead.place_id,
  status: "enriched",
  segment: lead.segment || "",
  legal_name: k.legal_name || "",
  core_business: k.core_business || "",
  manages_weg: yn(k.manages_weg),
  manages_whole_buildings: yn(k.manages_whole_buildings),
  does_billing: yn(k.does_billing),
  property_focus: k.property_focus || "",
  units_stated: (k.units_stated || "").replace(/\s+/g, " "),
  size_category: size,
  digital_level: k.digital_level || "",
  association: k.association || "",
  energy_signal: yn(k.energy_signal),
  growth_signal: yn(k.growth_signal),
  own_metering: yn(k.own_metering),
  consolidator: yn(k.consolidator),
  existing_customer: yn(existing),
  metering_providers: (k.metering_providers || []).join(", "),
  berlin_presence: k.berlin_presence || "",
  years_in_business: k.founding_year ? (new Date().getFullYear() - k.founding_year) : "",
  score: score,
  priority: priority,
  red_flag: flags.join("; "),
  score_reason: reasonPrefix + (k.score_reason || ""),
  score_breakdown: breakdown + (guardNotes.length ? ` | guardrails: ${guardNotes.join(", ")}` : ""),
  data_confidence: k.data_confidence || "",
  needs_review: review.length ? "yes – " + review.join("; ") : "no",
  general_email: general,
  contact_name: k.decision_maker?.name || "",
  contact_role: k.decision_maker?.role || "",
  contact_email: personal[0] || "",
  email_confidence: personal[0] ? "Verified (on website)" : "",
  enriched_at: now,
  evidence_urls: lead.evidence_urls || "",
}};
